512→func truncate(s string, maxLen int) string {
513→	if len(s) <= maxLen {
514→		return s
515→	}
516→	if maxLen <= 3 {
517→		return s[:maxLen]
518→	}
519→	return s[:maxLen-3] + "..."
520→}
