533→func truncate(s string, maxLen int) string {
534→	if len(s) <= maxLen {
535→		return s
536→	}
537→	if maxLen <= 3 {
538→		return s[:maxLen]
539→	}
540→	return s[:maxLen-3] + "..."
541→}
